const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>new Intl.NumberFormat('ar-SA',{maximumFractionDigits:2}).format(n),money=n=>num(n)+' ر.س';
const merchant=!document.body.classList.contains('store'),key='riwaq-bundles-v2';
function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
let saved=read(key,[]);if(!Array.isArray(saved))saved=[];let draft={id:null,name:'',description:'',price:0,items:[]},cart=[];let timer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(next){try{localStorage.setItem(key,JSON.stringify(next));saved=next;return true}catch{toast('تعذّر الحفظ. اسمح بالتخزين المحلي في المتصفح.');return false}}
const calc=(b,min=0)=>BundleCore.calculate(b,VARIANTS,DATA.products,min),opt=v=>Object.values(v.options||{}).join('، '),product=id=>DATA.products.find(p=>p.id===id);
function bundleCard(b){const r=calc(b);return `<article class="bundle-card"><div class="bundle-images">${r.rows.slice(0,3).map(({p})=>`<img src="${esc(p.main_image)}" alt="${esc(p.name)}" loading="lazy">`).join('')}</div><div class="body"><span class="eyebrow">${num(r.rows.length)} منتجات في باقة</span><h3>${esc(b.name)}</h3><p>${esc(b.description)}</p><ul>${r.rows.map(({p,v,q})=>`<li>${num(q)} × ${esc(p.name)} ${opt(v)?'— '+esc(opt(v)):''}</li>`).join('')}</ul><span class="old-price">${money(r.total)}</span><strong class="price">${money(Number(b.price))}</strong><br><span class="saving">وفّر ${money(r.savings)} · ${num(r.capacity)} باقة متاحة</span><div class="notes">${r.notes.map(esc).join('<br>')}</div><div class="actions">${merchant?`<button class="secondary" data-edit="${esc(b.id)}">تعديل</button><button class="secondary" data-delete="${esc(b.id)}">إلغاء الاعتماد</button>`:`<button data-cart-bundle="${esc(b.id)}" ${r.errors.length?'disabled':''}>أضف الباقة للسلة</button>`}</div></div></article>`}
function renderSaved(){const target=merchant?$('#saved-bundles'):$('#featured-products');const visible=merchant?saved:saved.filter(b=>!calc(b).errors.length);target.innerHTML=visible.length?visible.map(bundleCard).join(''):`<div class="empty">${merchant?'لم تعتمد أي باقة بعد. ابدأ باقتراح باقة ثم راجعها.':'لم تُعتمد باقات في هذا المتصفح بعد. جرّب صانع الباقات من لوحة التاجر.'}</div>`;if(!merchant)$('#featured-label').textContent=num(visible.length)+' باقات معتمدة'}
function syncFields(){draft.name=$('#bundle-name').value;draft.description=$('#bundle-description').value;draft.price=$('#bundle-price').value}
function updateMetrics(){syncFields();const minimum=Number($('#min-margin').value),r=calc(draft,minimum);if(!Number.isFinite(minimum)||minimum<0||minimum>95)r.errors.push('الهامش المستهدف يجب أن يكون بين 0 و95.');$('#metrics').innerHTML=[['أسعار المنتجات منفردة',money(r.total)],['تكلفة المنتجات',money(r.cost)],['التوفير للعميل',money(r.savings)],['الفرق عن التكلفة',money(r.profit)],['الهامش التقديري',num(r.margin)+'٪'],['باقات ممكنة من المخزون',num(r.capacity)]].map(([k,v])=>`<div class="metric"><span>${k}</span><strong>${v}</strong></div>`).join('');$('#validation').innerHTML=r.errors.map(e=>`<div class="notice error">${esc(e)}</div>`).join('')+r.notes.map(n=>`<div class="notice">${esc(n)}</div>`).join('')+(!r.errors.length?'<div class="notice good">الباقة جاهزة للمراجعة والاعتماد.</div>':'');$('#publish').disabled=!!r.errors.length;return r}
function renderEditor(){for(const [id,val] of [['bundle-name',draft.name],['bundle-description',draft.description],['bundle-price',draft.price]])$('#'+id).value=val;$('#bundle-items').innerHTML=draft.items.length?draft.items.map(i=>{const v=VARIANTS.find(v=>v.id===i.variant_id),p=product(v.product_id);return `<div class="bundle-item"><img src="${esc(p.main_image)}" alt="${esc(p.name)}"><div class="info"><strong>${esc(p.name)} ${opt(v)?'— '+esc(opt(v)):''}</strong><small>${money(v.price)} للقطعة · ${num(v.stock_quantity)} متاح</small></div><input type="number" min="1" step="1" value="${i.quantity}" data-qty="${v.id}" aria-label="كمية ${esc(p.name)} ${esc(opt(v))}"><button class="secondary" data-remove-item="${v.id}" aria-label="إزالة ${esc(p.name)}">×</button></div>`}).join(''):'<p class="empty">أضف منتجين على الأقل، أو ابدأ باقتراح.</p>';updateMetrics()}
if(merchant){$('#add-product').innerHTML=VARIANTS.map(v=>{const p=product(v.product_id);return `<option value="${v.id}" ${v.stock_quantity<=0?'disabled':''}>${esc(p.name)} ${opt(v)?'— '+esc(opt(v)):''} (${money(v.price)})${v.stock_quantity<=0?' — نافد':''}</option>`}).join('');$('#suggest').onclick=()=>{const templates={brew:{name:'بداية الترشيح',description:'قطّارة وفلاتر متوافقة بمقاس 02 مع قهوة إثيوبيا. لا تتضمن مطحنة أو غلاية.',price:109,ids:['var_008','var_010','var_001']},gift:{name:'هدية على رواق',description:'قهوة كولومبيا مع كوب سيراميك بيج وصندوق هدية. كوب واحد باللون المحدد.',price:115,ids:['var_020_1','var_002','var_026']},daily:{name:'روتين القهوة',description:'قهوة كولومبيا مع مطحنة يدوية أساسية وفرشاة تنظيف.',price:205,ids:['var_002','var_014','var_022']}};const t=templates[$('#idea').value];draft={id:null,name:t.name,description:t.description,price:t.price,items:t.ids.map(id=>({variant_id:id,quantity:1}))};renderEditor();toast('تم اقتراح الباقة. راجع السعر والمحتويات قبل الاعتماد.')};$('#new').onclick=()=>{draft={id:null,name:'',description:'',price:0,items:[]};renderEditor()};$('#add').onclick=()=>{syncFields();const id=$('#add-product').value,item=draft.items.find(i=>i.variant_id===id);if(item)item.quantity++;else draft.items.push({variant_id:id,quantity:1});renderEditor()};['bundle-name','bundle-description','bundle-price','min-margin'].forEach(id=>$('#'+id).addEventListener('input',updateMetrics));$('#bundle-items').oninput=e=>{if(e.target.dataset.qty){draft.items.find(i=>i.variant_id===e.target.dataset.qty).quantity=Number(e.target.value);updateMetrics()}};$('#publish').onclick=()=>{if(updateMetrics().errors.length)return;const b=JSON.parse(JSON.stringify(draft));b.id=b.id||'bundle-'+Date.now();b.price=Number(b.price);const next=saved.filter(x=>x.id!==b.id).concat(b);if(persist(next)){draft.id=b.id;renderSaved();toast('تم اعتماد الباقة في واجهة العميل بهذا المتصفح.')}};renderEditor()}
function renderCatalog(){const q=$('#search').value.trim(),cat=$('#category').value;const ps=DATA.products.filter(p=>(!cat||p.category_id===cat)&&p.name.includes(q));$('#products').innerHTML=ps.length?ps.map(p=>`<article class="product-card"><img src="${esc(p.main_image)}" alt="${esc(p.name)}" loading="lazy"><div class="product-info"><h3>${esc(p.name)}</h3><span class="price">${money(p.price)}</span><button class="secondary" data-detail="${p.id}">عرض المنتج</button></div></article>`).join(''):'<div class="empty">لا توجد نتائج. جرّب بحثًا مختلفًا.</div>'}
function detail(id){const p=product(id),vs=VARIANTS.filter(v=>v.product_id===id);$('#detail-body').innerHTML=`<img class="detail-image" src="${esc(p.main_image)}" alt="${esc(p.name)}"><h2>${esc(p.name)}</h2><p>${esc(p.short_description||'الوصف غير متوفر.')}</p><ul>${p.specifications.map(s=>`<li>${esc(s.label_ar)}: ${esc(Array.isArray(s.value)?s.value.join('، '):s.value)}</li>`).join('')}</ul><label>الخيار<select id="detail-variant">${vs.map(v=>`<option value="${v.id}" ${v.stock_quantity<=0?'disabled':''}>${esc(opt(v)||'الخيار الأساسي')} — ${money(v.price)} (${num(v.stock_quantity)} متاح)</option>`).join('')}</select></label><button data-cart-product="${id}" ${vs.every(v=>v.stock_quantity<=0)?'disabled':''}>إضافة للسلة التجريبية</button>`;$('#detail').showModal()}
function addCart(line){const used={};for(const l of cart)for(const i of l.items)used[i.variant_id]=(used[i.variant_id]||0)+i.quantity;for(const i of line.items){const v=VARIANTS.find(v=>v.id===i.variant_id);if(!v||v.stock_quantity<(used[v.id]||0)+i.quantity){toast('الكمية في السلة تتجاوز المخزون المتاح لأحد المنتجات.');return}}cart.push(line);$('#cart-count').textContent=num(cart.length);toast('أضيفت إلى السلة التجريبية.')}
function showCart(){let total=cart.reduce((s,l)=>s+l.price,0);$('#cart-body').innerHTML=cart.length?cart.map((l,i)=>`<div class="cart-row"><div><strong>${esc(l.name)}</strong><p>${l.items.map(x=>{const v=VARIANTS.find(v=>v.id===x.variant_id);return num(x.quantity)+' × '+esc(product(v.product_id).name)+' '+esc(opt(v))}).join('<br>')}</p>${money(l.price)}</div><button class="secondary" data-remove-cart="${i}">حذف</button></div>`).join('')+`<h3>إجمالي المنتجات والباقات: ${money(total)}</h3><p>الشحن غير محسوب. لا يوجد دفع حقيقي.</p>`:'<div class="empty">السلة فارغة.</div>';if(!$('#cart').open)$('#cart').showModal()}
if(!merchant){$('#category').innerHTML+=DATA.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('#search').oninput=renderCatalog;$('#category').onchange=renderCatalog;$('#cart-button').onclick=showCart;document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());renderCatalog()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.removeItem){syncFields();draft.items=draft.items.filter(i=>i.variant_id!==d.removeItem);renderEditor()}if(d.edit){draft=JSON.parse(JSON.stringify(saved.find(x=>x.id===d.edit)));renderEditor();$('.builder').scrollIntoView({behavior:'smooth'})}if(d.delete){if(persist(saved.filter(x=>x.id!==d.delete))){if(draft.id===d.delete)draft.id=null;renderSaved();toast('تم إلغاء اعتماد الباقة.')}}if(d.detail)detail(d.detail);if(d.cartBundle){const x=saved.find(x=>x.id===d.cartBundle);if(x&&!calc(x).errors.length)addCart({name:x.name,price:Number(x.price),items:JSON.parse(JSON.stringify(x.items))})}if(d.cartProduct){const v=VARIANTS.find(v=>v.id===$('#detail-variant').value);if(v)addCart({name:product(v.product_id).name,price:v.price,items:[{variant_id:v.id,quantity:1}]})}if(d.removeCart!==undefined){cart.splice(Number(d.removeCart),1);$('#cart-count').textContent=num(cart.length);showCart()}});
window.addEventListener('storage',e=>{if(e.key===key){saved=read(key,[]);renderSaved()}});renderSaved();
